    CDefPointer<const CCombatTypeDef> type_def;
    CTCCombat* combat;
    if (pthing && !pthing->IsDead() && pthing->GetTC(&combat)) {
        if (pthing->PeekDefinitionManager().GetDef(combat_type, &type_def))
            combat->SetCombatType(type_def);
    }
